Analyze the following code and determine what happens when the GameObject with this script enters a trigger zone tagged as "Checkpoint":
using UnityEngine;

public class CheckpointTrigger : MonoBehaviour
{
    public GameObject checkpointEffect;

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Checkpoint"))
        {
            checkpointEffect.SetActive(true);
            Debug.Log("Checkpoint Reached!");
        }
    }
}

Given the following script snippet attached to a GameObject with a Rigidbody component, what will happen when the space bar is pressed?
public Rigidbody rb;
public float forceMagnitude = 500;

void Update()
{
    if (Input.GetKeyDown(KeyCode.Space))
    {
        rb.AddForce(Vector3.up * forceMagnitude);
    }
}
